            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s006_e02", prompt = "Combien de coupures de [a,b,c] sont générées par app(P,S,[a,b,c]) ?", codeSnippet = "app([],B,B).\napp([H|T],B,[H|R]) :- app(T,B,R).\n\n?- app(P,S,[a,b,c]).", options = listOf("4", "2", "3", "6"), correctOptionIndex = 0, explanation = "Les préfixes possibles sont [], [a], [a,b] et [a,b,c]. Chacun impose un suffixe unique.", hint = "N’oublie pas les deux coupures aux extrémités."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s006_e03", prompt = "Quelle réponse donne l’inversion avec accumulateur ?", codeSnippet = "inv_acc([],A,A).\ninv_acc([H|T],A,R) :- inv_acc(T,[H|A],R).\n\n?- inv_acc([a,b,c],[],R).", options = listOf("R = [a,b,c]", "R = [[c,b,a]]", "R = []", "R = [c,b,a]"), correctOptionIndex = 3, explanation = "L’accumulateur passe par [a], [b,a], [c,b,a]. Le cas vide transmet ce dernier état à R.", hint = "La nouvelle tête est placée devant l’accumulateur."),
            Exercise.MultipleChoice(id = "learn_prolog_now_2026_s006_e04", prompt = "Pourquoi l’inversion naïve avec append à chaque retour peut-elle être quadratique ?", options = listOf("Le nombre d’éléments double forcément à chaque appel.", "Une liste ne peut jamais être inversée.", "Chaque retour peut reparcourir une liste plus longue, donnant une somme 0+1+...+(n-1).", "append est toujours gratuit."), correctOptionIndex = 2, explanation = "La concaténation parcourt son premier argument ; les longueurs cumulées sur les retours donnent n(n-1)/2 dans ce mode.", hint = "Additionne le travail de tous les niveaux."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s006_e05", prompt = "Quel élément est reconnu comme dernier par cette définition ?", codeSnippet = "app([],B,B).\napp([H|T],B,[H|R]) :- app(T,B,R).\ndernier(L,X) :- app(_,[X],L).\n\n?- dernier([a,b,c],X).", options = listOf("X = [c]", "X = c", "X = a", "X = b"), correctOptionIndex = 1, explanation = "La relation exige un suffixe composé exactement d’un élément. Dans [a,b,c], seul c peut former ce suffixe.", hint = "La seconde liste a la forme [X], pas X.")
        ),
        objective = "Utiliser append comme relation et suivre un accumulateur de liste.",
        learningNotes = "La relation append(A,B,C) dit que C est la concaténation de A et B. Le cas append([],B,B) et la règle qui déplace la première tête de A vers C suffisent à la définir. Selon les arguments connus, on peut concaténer, chercher un suffixe ou énumérer toutes les coupures d'une liste finie. Une liste de longueur trois possède quatre coupures, en incluant les listes vides aux deux extrémités. Inverser une liste par récursion puis append peut refaire de nombreux parcours : avec une entrée finie connue, les longueurs parcourues s'additionnent et conduisent à un coût quadratique. Une inversion avec accumulateur place chaque tête devant une liste déjà construite et avance sur la queue, ce qui évite ces concaténations répétées. Les modes connus et recherchés restent importants pour la terminaison.",
        sourceUrls = listOf("https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlch6", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse24", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse25", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse26", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse27"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 6,
        sourceTitle = "More Lists",
        sessionKind = "lesson"
    )

    private fun lesson007() = Lesson(
        id = "learn_prolog_now_2026_s007",
        title = "Reconnaître un langage avec une DCG",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s007_e01", prompt = "Cette grammaire reconnaît-elle toute la liste proposée ?", codeSnippet = "s --> np,vp.\nnp --> [ana].\nvp --> [dort].\n\n?- s([ana,dort],[]).", options = listOf("Oui : le reste final est vide.", "Non, car ana n’est pas un terminal.", "Non, car une DCG ne consomme aucun symbole.", "Oui, mais il reste toujours [dort]."), correctOptionIndex = 0, explanation = "np consomme ana et vp consomme dort ; les deux terminaux épuisent l’entrée et laissent [].", hint = "Suis le reste après chaque non-terminal."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s007_e02", prompt = "Quel reste R laisse la reconnaissance d’un préfixe ?", codeSnippet = "s --> [ana,dort].\n\n?- s([ana,dort,vite],R).", options = listOf("R = []", "R = [ana,dort,vite]", "Échec, car tout appel de DCG impose un reste vide.", "R = [vite]"), correctOptionIndex = 3, explanation = "Le prédicat s consomme exactement ana puis dort. La dernière partie de l’entrée devient R, qui n’était pas imposé vide.", hint = "Une entrée et un reste représentent la portion consommée."),
            Exercise.MultipleChoice(id = "learn_prolog_now_2026_s007_e03", prompt = "Quelle traduction correspond à s --> np,vp. ?", options = listOf("s(A,C) :- np(C,A), vp(C,A).", "s(A,C) :- np(A,B), vp(A,C).", "s(A,C) :- np(A,B), vp(B,C).", "s(A,C) :- np(A,C), vp(A,C)."), correctOptionIndex = 2, explanation = "Le reste B de np devient l’entrée de vp. C est le reste après les deux reconnaissances.", hint = "Relie la sortie d’une étape à l’entrée de la suivante."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s007_e04", prompt = "Avec cette DCG, la liste [a,a,b,b] appartient-elle au langage reconnu ?", codeSnippet = "s --> [].\ns --> [a],s,[b].\n\n?- s([a,a,b,b],[]).", options = listOf("Non, car le cas vide empêche toute récursion.", "Oui : deux applications récursives entourent le cas vide.", "Non, car seuls un a et un b sont acceptés.", "Oui, même si les nombres de a et b diffèrent."), correctOptionIndex = 1, explanation = "Chaque règle récursive ajoute un a avant et un b après ; le cas vide termine la structure. On obtient exactement a^n b^n.", hint = "Chaque niveau conserve le même nombre de a et de b."),
            Exercise.MultipleChoice(id = "learn_prolog_now_2026_s007_e05", prompt = "Pourquoi la règle s --> s,[et],s. est-elle risquée dans un analyseur descendant ordinaire ?", options = listOf("Son premier appel récursif ne consomme aucun terminal avant de recommencer s.", "Elle consomme toujours toute la phrase avant de récursiver.", "Les DCG interdisent tout symbole et.", "Elle garantit un arbre unique."), correctOptionIndex = 0, explanation = "La traduction commence par le même non-terminal sur la même entrée ; la recherche peut poursuivre cette branche indéfiniment.", hint = "Regarde ce qui change avant le premier appel récursif.")
        ),
        objective = "Interpréter terminaux et non-terminaux et suivre les listes différence.",
        learningNotes = "Une grammaire décrit comment une phrase se compose de catégories. Une DCG utilise la notation --> : s --> np,vp. demande un groupe nominal suivi d'un groupe verbal ; les terminaux s'écrivent dans des listes comme [ana]. Prolog traduit chaque non-terminal en prédicat recevant deux arguments supplémentaires : la liste d'entrée et le reste après consommation. La composition relie le reste de la première partie à l'entrée de la seconde. Reconnaître toute une phrase exige un reste final vide ; un reste non vide signifie seulement qu'un préfixe a été reconnu. Les DCG peuvent aussi générer des phrases sur retour arrière. Leur traduction reste soumise à la recherche de Prolog : une récursion gauche peut boucler, et déplacer une clause ne suffit pas à garantir la terminaison sur tous les appels.",
        sourceUrls = listOf("https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlch7", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse28", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse29", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse30", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse31"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 7,
        sourceTitle = "Definite Clause Grammars",
        sessionKind = "lesson"
    )

    private fun lesson008() = Lesson(
        id = "learn_prolog_now_2026_s008",
        title = "Ajouter des traits et construire un arbre syntaxique",
        xpReward = 20,
        isLocked = false,
