            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s008_e01", prompt = "Quel accord impose le partage de N ?", codeSnippet = "s --> np(N),vp(N).\nnp(sg) --> [chat].\nnp(pl) --> [chats].\nvp(sg) --> [dort].\nvp(pl) --> [dorment].", options = listOf("Le nom et le verbe doivent être le même mot.", "La phrase doit avoir N mots, nécessairement numérique.", "Les deux listes d’entrée doivent être vides dès le début.", "Le nom et le verbe doivent posséder le même nombre grammatical."), correctOptionIndex = 3, explanation = "N est partagé par les deux appels. Une valeur sg obtenue pour le sujet doit aussi convenir au verbe.", hint = "Suis la même variable dans les deux catégories."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s008_e02", prompt = "La phrase [chats,dort] satisfait-elle cette grammaire d’accord ?", codeSnippet = "s --> np(N),vp(N).\nnp(sg) --> [chat].\nnp(pl) --> [chats].\nvp(sg) --> [dort].\nvp(pl) --> [dorment].\n\n?- s([chats,dort],[]).", options = listOf("Oui, en affectant deux valeurs différentes au même N.", "Elle provoque nécessairement une erreur arithmétique.", "Non : pl et sg ne s’unifient pas.", "Oui, car tous les mots sont présents dans le lexique."), correctOptionIndex = 2, explanation = "np impose N=pl, puis vp sur dort exige N=sg. Les deux atomes distincts ne s’unifient pas.", hint = "La présence des mots ne suffit pas à satisfaire le trait partagé."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s008_e03", prompt = "Quel arbre est construit pour [ana,dort] ?", codeSnippet = "s(phrase(N,V)) --> np(N),vp(V).\nnp(nom(ana)) --> [ana].\nvp(verbe(dort)) --> [dort].\n\n?- s(T,[ana,dort],[]).", options = listOf("T = []", "T = phrase(nom(ana),verbe(dort))", "T = [ana,dort]", "T = phrase(verbe(dort),nom(ana))"), correctOptionIndex = 1, explanation = "Les deux arguments explicites sont unifiés aux termes nom(ana) et verbe(dort), puis assemblés dans phrase(N,V).", hint = "Sépare l’arbre construit des listes de reconnaissance."),
            Exercise.MultipleChoice(id = "learn_prolog_now_2026_s008_e04", prompt = "Dans mot --> [W],{lex(W,nom)}., quel rôle a le but entre accolades ?", options = listOf("Vérifier la catégorie de W dans un prédicat Prolog sans consommer un terminal supplémentaire.", "Consommer un deuxième mot obligatoirement.", "Créer automatiquement un nouveau fichier de lexique.", "Remplacer W par une liste vide."), correctOptionIndex = 0, explanation = "[W] consomme un terminal ; lex(W,nom) vérifie ensuite une relation ordinaire sans ajouter les arguments de listes de DCG.", hint = "Seuls les terminaux et non-terminaux de la grammaire gèrent la consommation ici."),
            Exercise.MultipleChoice(id = "learn_prolog_now_2026_s008_e05", prompt = "Un non-terminal possédant deux arguments explicites, comme regle(T,N), devient un prédicat de quelle arité ?", options = listOf("2", "3", "6", "4"), correctOptionIndex = 3, explanation = "Les deux arguments explicites sont conservés et les listes d’entrée et de reste en ajoutent deux : arité quatre.", hint = "Ajoute les deux arguments automatiques de DCG.")
        ),
        objective = "Partager des arguments de DCG et distinguer buts auxiliaires et terminaux.",
        learningNotes = "Une DCG peut transporter des arguments explicites en plus des deux listes introduites automatiquement. Ils servent par exemple à faire partager le nombre grammatical d'un sujet et d'un verbe : s --> np(N),vp(N). impose la même valeur N. Un argument peut aussi construire un arbre sous forme de terme, comme phrase(nom(ana),verbe(dort)), plutôt que produire seulement une réussite. Les accolades {But} insèrent un but Prolog ordinaire : un accès au lexique ou un calcul peut alors compléter la reconnaissance sans consommer lui-même un terminal. Séparer lexique et règles évite de recopier la structure grammaticale à chaque nouveau mot. Ces arguments restent de simples termes unifiés ; ils ne fournissent pas automatiquement un système général de traits ni une autre stratégie d'analyse que celle de Prolog.",
        sourceUrls = listOf("https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlch8", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse32", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse33", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse34", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse35", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse36"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 8,
        sourceTitle = "More Definite Clause Grammars",
        sessionKind = "lesson"
    )

    private fun lesson009() = Lesson(
        id = "learn_prolog_now_2026_s009",
        title = "Examiner les termes et lire les opérateurs",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s009_e01", prompt = "X est fraîche. Que fait ce test d’identité ?", codeSnippet = "?- X == a.", options = listOf("Il réussit avec X = [].", "Il change le fait a dans la base.", "Il échoue et ne lie pas X.", "Il réussit avec X = a."), correctOptionIndex = 2, explanation = "Une variable libre n’est pas actuellement identique à l’atome a. == ne réalise aucune unification pour les rendre identiques.", hint = "Le test interdit précisément la création d’une nouvelle liaison."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s009_e02", prompt = "Que devient le test d’identité après l’unification des variables ?", codeSnippet = "?- X = Y, X == Y.", options = listOf("Il transforme X en entier.", "Il réussit : X et Y désignent la même variable.", "Il échoue toujours parce que deux noms sont écrits.", "Il lie X à l’atome y."), correctOptionIndex = 1, explanation = "X=Y établit une liaison entre les deux variables ; leur identité actuelle satisfait alors X==Y.", hint = "Des noms différents peuvent référencer une même variable."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s009_e03", prompt = "Quelles valeurs extrait functor ?", codeSnippet = "?- functor(route(a,b),F,N).", options = listOf("F = route, N = 2", "F = a, N = b", "F = route(a,b), N = 1", "F = route, N = 3"), correctOptionIndex = 0, explanation = "Le terme route(a,b) possède le foncteur route et exactement deux arguments.", hint = "Le foncteur ne comprend pas ses arguments."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s009_e04", prompt = "Quelle valeur extrait la position demandée ?", codeSnippet = "?- arg(2,point(3,8),X).", options = listOf("X = 3", "X = point", "X = [3,8]", "X = 8"), correctOptionIndex = 3, explanation = "arg/3 utilise ici des positions commençant à un : le deuxième argument de point(3,8) est 8.", hint = "Ne transpose pas l’indexation à partir de zéro des autres langages."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s009_e05", prompt = "Quel terme construit l’opérateur =.. ?", codeSnippet = "?- T =.. [couleur,ciel,bleu].", options = listOf("T = ciel(bleu,couleur)", "T = couleur([ciel,bleu])", "T = couleur(ciel,bleu)", "T = [couleur,ciel,bleu]"), correctOptionIndex = 2, explanation = "Le premier élément de la liste devient le foncteur ; les deux suivants deviennent ses deux arguments distincts.", hint = "L’opérateur établit une relation entre terme et liste de description."),
            Exercise.MultipleChoice(id = "learn_prolog_now_2026_s009_e06", prompt = "Lequel de ces termes est clos ?", options = listOf("f(_,b)", "f(a,g(b))", "f(a,X)", "X"), correctOptionIndex = 1, explanation = "f(a,g(b)) ne contient aucune variable. Les trois autres en contiennent au moins une, y compris le souligné anonyme.", hint = "Inspecte aussi les termes imbriqués.")
        ),
        objective = "Distinguer identité et unification et décomposer une structure.",
        learningNotes = "Les termes peuvent être inspectés sans toujours chercher à les unifier. Le test == vérifie l'identité actuelle de deux termes sans créer de liaison ; = essaie au contraire de rendre les termes identiques par substitution. Deux variables fraîchement distinctes ne sont donc pas identiques, mais peuvent être unifiées. Un terme clos, ou ground, ne contient aucune variable, même dans ses sous-termes. functor/3 extrait le foncteur et l'arité ; arg/3 accède à un argument, et =.. relie un terme à la liste formée de son foncteur puis de ses arguments. Les opérateurs changent la notation et le groupement syntaxique, pas automatiquement la valeur : 2+3*4 représente une structure imbriquée avant toute évaluation. Une inspection correcte tient donc compte des priorités et du type de comparaison réellement demandé.",
        sourceUrls = listOf("https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlch9", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse37", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse38", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse39", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse40", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse41", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse42"),
        requiresPreviousLesson = true,
        sourceSessionNumber = 9,
        sourceTitle = "A Closer Look at Terms",
        sessionKind = "lesson"
    )

    private fun lesson010() = Lesson(
        id = "learn_prolog_now_2026_s010",
        title = "Contrôler le retour arrière et nier par échec",
        xpReward = 20,
        isLocked = false,
        exercises = listOf(
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s010_e01", prompt = "Quelles réponses donne premier(X), avec les clauses dans cet ordre ?", codeSnippet = "choix(a).\nchoix(b).\npremier(X) :- choix(X), !.\npremier(autre).\n\n?- premier(X).", options = listOf("Échec.", "X = a seulement.", "X = a ; X = b ; X = autre.", "X = autre seulement."), correctOptionIndex = 1, explanation = "choix(X) fournit d’abord a. La coupure engage cet appel de premier et supprime choix(b) ainsi que la clause premier(autre).", hint = "La coupure est atteinte après le premier choix réussi."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s010_e02", prompt = "La présence d’une coupure suffit-elle à faire réussir p(X) ici ?", codeSnippet = "q(a).\nq(b).\nr(b).\np(X) :- q(X), !, r(X).\np(z).\n\n?- p(X).", options = listOf("Non : le candidat a est engagé, puis r(a) échoue sans alternative restante pour p.", "Oui, avec X = a.", "Oui, avec X = b.", "Oui, avec X = z."), correctOptionIndex = 0, explanation = "q(a) est le premier succès. ! supprime les autres choix de q et de p ; r(a) échoue et le programme ne revient ni à q(b) ni à p(z).", hint = "Suis aussi les buts placés après la coupure."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s010_e03", prompt = "Avec la seule couleur rouge connue, que donne la requête fermée ?", codeSnippet = "couleur(rouge).\n\n?- \\+ couleur(bleu).", options = listOf("Elle ajoute couleur(bleu) à la base.", "Elle échoue parce que bleu est un atome.", "Elle retourne toutes les couleurs possibles.", "Elle réussit : couleur(bleu) ne peut pas être prouvé."), correctOptionIndex = 3, explanation = "La négation par échec teste le but couleur(bleu), qui échoue face à couleur(rouge). Elle ne modifie pas la base.", hint = "La variable n’est pas libre : la couleur testée est déjà fixée."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s010_e04", prompt = "La requête suivante énumère-t-elle les couleurs autres que rouge ?", codeSnippet = "couleur(rouge).\n\n?- \\+ couleur(X).", options = listOf("Oui, avec X = bleu uniquement.", "Elle crée une nouvelle variable pour chaque couleur absente.", "Non : elle échoue dès que couleur(X) trouve rouge.", "Oui, elle génère tous les autres atomes."), correctOptionIndex = 2, explanation = "Le but positif possède une solution, donc sa négation échoue. Aucune liste de couleurs absentes n’est construite.", hint = "La négation par échec n’est pas un générateur de complément."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s010_e05", prompt = "Quelle réponse produit d’abord la génération puis le test négatif ?", codeSnippet = "fruit(pomme).\nfruit(poire).\nabime(poire).\n\n?- fruit(X), \\+ abime(X).", options = listOf("Aucune réponse.", "X = pomme seulement.", "X = poire seulement.", "X = pomme ; X = poire."), correctOptionIndex = 1, explanation = "fruit(X) produit pomme, qui n’est pas abîmée selon la base. La valeur poire est ensuite rejetée par le test.", hint = "Le premier but instancie X avant la négation."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s010_e06", prompt = "Que change l’inversion de ces deux buts ?", codeSnippet = "fruit(pomme).\nfruit(poire).\nabime(poire).\n\n?- \\+ abime(X), fruit(X).", options = listOf("La requête échoue avant toute génération de fruit, car abime(X) possède une solution.", "Elle produit exactement pomme comme avant.", "Elle répare toujours les erreurs de terminaison.", "Elle efface le fait abime(poire)."), correctOptionIndex = 0, explanation = "Avec X libre, abime(X) réussit pour poire. La négation échoue immédiatement, donc fruit(X) n’est jamais exécuté.", hint = "L’ordre des buts est opérationnellement significatif.")
        ),
        objective = "Comprendre la portée d’une coupure et l’effet de l’ordre des buts.",
        learningNotes = "La coupure ! réussit lorsqu'elle est rencontrée et supprime certains choix de retour arrière faits depuis l'entrée dans l'appel courant, notamment les autres clauses de ce prédicat. Elle ne garantit pas que les buts suivants réussiront. Un premier candidat retenu avant ! peut donc faire échouer tout l'appel si un test ultérieur le rejette, même lorsqu'un autre candidat aurait convenu sans coupure. Une coupure dite verte retire seulement des alternatives redondantes pour le contrat prévu ; une coupure rouge peut modifier les réponses logiques. La négation par échec \\+ G réussit lorsque la recherche de G échoue. Ce n'est pas une énumération des valeurs qui rendent G faux : avec des variables libres, elle peut échouer dès qu'une solution existe. Produire d'abord une valeur puis tester sa négation donne souvent le mode attendu.",
        sourceUrls = listOf("https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlch10", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse43", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse44", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse45", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse46", "https://www.let.rug.nl/bos/lpn/lpnpage.php?pagetype=html&pageid=lpn-htmlse47"),
