        exercises = listOf(
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s011_e01", prompt = "Quelle liste conserve l’ordre et les doublons des réponses ?", codeSnippet = "p(b).\np(a).\np(b).\n\n?- findall(X,p(X),L).", options = listOf("L = [b,a,b]", "L = [a,b]", "L = [b,a]", "L = []"), correctOptionIndex = 0, explanation = "findall collecte chaque preuve réussie dans l’ordre des faits. Les deux faits p(b) produisent deux occurrences de b.", hint = "Une collecte de solutions n’est pas automatiquement un ensemble."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s011_e02", prompt = "Quelle liste donne setof sur les mêmes faits ?", codeSnippet = "p(b).\np(a).\np(b).\n\n?- setof(X,p(X),L).", options = listOf("L = [b,a,b]", "L = [b,a]", "L = [a,a,b]", "L = [a,b]"), correctOptionIndex = 3, explanation = "setof retire les doublons et trie les atomes selon l’ordre des termes. a précède b.", hint = "Compare le contrat de setof à celui de findall."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s011_e03", prompt = "Aucun fait p(b) n’existe. Quelle différence observe-t-on entre ces collectes ?", codeSnippet = "p(a).\n\n?- findall(X,(p(X),X=b),L).\n?- bagof(X,(p(X),X=b),L).", options = listOf("Les deux ajoutent p(b).", "findall échoue ; bagof réussit avec L=[b].", "findall réussit avec L=[] ; bagof échoue.", "Les deux réussissent avec L=[]."), correctOptionIndex = 2, explanation = "findall possède un résultat vide. bagof exige au moins une solution pour produire un groupe.", hint = "L’absence de solution n’est pas représentée de la même façon."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s011_e04", prompt = "Pourquoi cette requête bagof produit-elle une liste par animal ?", codeSnippet = "couleur(chat,noir).\ncouleur(chat,blanc).\ncouleur(chien,brun).\n\n?- bagof(C,couleur(A,C),L).", options = listOf("Chaque fait doit avoir un foncteur différent.", "A est une variable libre du but qui ne figure pas dans le modèle C.", "C est nécessairement une constante.", "bagof mélange toujours toutes les valeurs sans regroupement."), correctOptionIndex = 1, explanation = "Le modèle est C et le but contient aussi A. bagof regroupe les couleurs par valeur de A : chat puis chien dans cet exemple.", hint = "Repère les variables du but absentes du premier argument."),
            Exercise.CodeChallenge(id = "learn_prolog_now_2026_s011_e05", prompt = "La base dynamique p/1 est initialement vide. Quel ordre retrouve findall après ces ajouts ?", codeSnippet = "% Hypothese : p/1 dynamique, sans clause initiale.\n?- assertz(p(b)), assertz(p(c)), asserta(p(a)),\n   findall(X,p(X),L).", options = listOf("L = [a,b,c]", "L = [b,c,a]", "L = [c,b,a]", "L = [a,c,b]"), correctOptionIndex = 0, explanation = "assertz ajoute b puis c en fin de base. asserta insère a au début. La collecte suit donc a,b,c.", hint = "Suis la position d’insertion de chaque clause.")
        ),
        objective = "Choisir findall, bagof ou setof selon le résultat recherché.",
        learningNotes = "Les solutions d'un but peuvent être réunies dans une liste. findall(Modele,But,Liste) collecte les instances du modèle dans l'ordre de recherche, conserve les doublons et produit [] quand aucun succès n'existe. bagof regroupe les réponses selon les variables libres du but qui ne figurent pas dans le modèle ; une quantification avec ^ peut retirer une variable de ce regroupement. setof effectue aussi ce regroupement, puis trie les éléments et retire les doublons. bagof et setof échouent lorsqu'il n'existe aucun résultat. Les prédicats dynamiques ajoutent une dimension d'état : asserta place une clause au début, assertz à la fin et retract retire une clause correspondante. Ces effets ne sont pas de simples liaisons annulées par retour arrière. Les exemples supposent une base initiale annoncée afin que l'ordre et le contenu restent déterminés.",
